#include <vector>
#include <cstddef>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;

    // In-place LU factorization without pivoting (Doolittle-style storage):
    // - U is stored on and above the diagonal
    // - L is stored below the diagonal with implied unit diagonal
    //
    // For each step k:
    //   1) Compute multipliers L(i,k) = A(i,k) / A(k,k) for i > k
    //   2) Update trailing submatrix:
    //        A(i,j) -= L(i,k) * A(k,j), for i,j > k
    //
    // Parallelization strategy:
    // - The normalization of column k over rows i>k is parallelized.
    // - The trailing update is parallelized over rows i>k.
    // Each thread writes to distinct A[i*N + ...] locations, so this is safe
    // for any thread count. The implicit barrier at the end of each omp for
    // ensures correct ordering between phases.

    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];

        // Compute L(i,k) for i = k+1..N-1
        #pragma omp parallel for default(none) shared(A, N, k, pivot)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k + 1);
             ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            const size_t i = static_cast<size_t>(ii);
            A[i * N + k] /= pivot;
        }

        // Update trailing submatrix A(i,j) for i,j = k+1..N-1
        #pragma omp parallel for default(none) shared(A, N, k)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k + 1);
             ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            const size_t i = static_cast<size_t>(ii);
            const double lik = A[i * N + k];
            const size_t row_i = i * N;
            const size_t row_k = k * N;

            for (size_t j = k + 1; j < N; ++j) {
                A[row_i + j] -= lik * A[row_k + j];
            }
        }
    }
}
